"""Descriptive weight concentration, not an adaptive-noise confidence estimate."""
import numpy as np


def summary(values):
    if not np.isfinite(values).all():raise ValueError('Finite diagnostic map required')
    return dict(mean=float(np.mean(values)),q10=float(np.quantile(values,.1)),median=float(np.median(values)),
                q90=float(np.quantile(values,.9)),minimum=float(np.min(values)),maximum=float(np.max(values)))


def accumulate_scaled_squared(squared,old_scale,new_scale,weight):
    """Track sum((w/max(w))^2) without squaring tiny unnormalised weights."""
    ratio=np.zeros_like(new_scale);relative=np.zeros_like(new_scale)
    np.divide(old_scale,new_scale,out=ratio,where=new_scale>0)
    np.divide(weight,new_scale,out=relative,where=new_scale>0)
    return squared*ratio*ratio+relative*relative


def describe_weights(total,squared,own,weighted_radius2):
    """squared is sum((w/own)^2), with the self weight already included."""
    if not (total.shape==squared.shape==own.shape==weighted_radius2.shape) or total.size==0 or any(not np.isfinite(v).all() or np.any(v<0) for v in (total,squared,own,weighted_radius2)):
        raise ValueError('Compatible nonnegative finite weight maps required')
    valid=total>0
    if np.any(valid & (squared<=0)):raise ValueError('Positive total needs positive squared sum')
    neff=np.ones_like(total);share=np.ones_like(total);radius2=np.zeros_like(total)
    if np.any(valid & (own<=0)):raise ValueError('Positive weight total needs positive maximum')
    relative_total=np.zeros_like(total)
    np.divide(total,own,out=relative_total,where=valid)
    np.divide(relative_total*relative_total,squared,out=neff,where=valid)
    np.divide(own,total,out=share,where=valid)
    np.divide(weighted_radius2,total,out=radius2,where=valid)
    if np.any(neff<1-1e-8) or np.any(neff>441+1e-8) or np.any(share>1+1e-8):raise ValueError('Invalid normalized weight statistics')
    return dict(effective_neighbors=summary(neff),self_weight_share=summary(share),
        rms_displacement_pixels=summary(np.sqrt(radius2)),inverse_effective_neighbors=summary(1/neff),
        identity_underflow_fraction=float(np.mean(~valid)),
        note='neff computed after normalizing weights by maximum to avoid squared-weight underflow;own max weight included.1/neff is weight concentration,not calibrated residual variance when weights depend on data or noise is correlated.')

