"""Three existing NLM reconstructions on identical supports and a common flat-noise target."""
import argparse
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_semantic_comparison import noise_model,reconstruct,measures,STRENGTHS
from study_noise_semantic_joint import reconstruct_joint,flat_noise
from study_noise_patch_aggregation import aggregate
from study_noise_sure_feasibility import color

METHODS=('scalar','joint_centre','joint_overlap')


def run_method(method,image,truth,model,h):
    if image.ndim!=3 or image.shape[0]!=3 or image.shape!=truth.shape or min(image.shape[1:])<=28:
        raise ValueError('Matching three-plane inputs and halo14 required')
    rect=(14,14,image.shape[2]-28,image.shape[1]-28)
    if method=='joint_overlap':return aggregate(image,truth,model,h)
    if method=='joint_centre':return reconstruct_joint(image,truth,model,h,rect)
    if method=='scalar':
        outputs=[reconstruct(image[c],truth[c],model,h,False,rect) for c in range(3)]
        return tuple(np.stack([r[k] for r in outputs]) for k in range(3))
    raise ValueError('Unknown comparison method')


def flat_measure(method,noise,model,h):
    output,_,_=run_method(method,noise,np.zeros_like(noise),model,h)
    per_plane=np.std(output,axis=(1,2))
    return dict(aggregate_std=float(np.sqrt(np.mean(per_plane**2))),per_plane_std=per_plane.tolist())


def common_target(scans,preferred=None):
    if set(scans)!=set(METHODS) or any(len(v)!=len(STRENGTHS) or not np.isfinite(v).all() or min(v)<=0 for v in scans.values()):
        raise ValueError('Positive finite strength scans required')
    if any(any(b>a+1e-7 for a,b in zip(v,v[1:])) for v in scans.values()):
        return dict(status='abstained_nonmonotone')
    low=max(v[-1] for v in scans.values());high=min(v[0] for v in scans.values())
    if not low<high:return dict(status='abstained_no_common_interval',interval=[low,high])
    if preferred is not None and not low<=preferred<=high:
        return dict(status='abstained_fixed_target_unreachable',interval=[low,high],target=preferred)
    return dict(status='common_target_available',interval=[low,high],target=preferred if preferred is not None else float(np.sqrt(low*high)))


def calibrate(colored,model,previous,can_reuse):
    key='binomial_correlated' if colored else 'white';noise=flat_noise(26012601,colored)
    scans={};sources={}
    for method in METHODS:
        if method=='joint_overlap' and can_reuse:
            scan=previous['calibrations'][key]['strength_scan']
            if [pair[0] for pair in scan]!=list(STRENGTHS):raise ValueError('Changed archived strength scan')
            scans[method]=[pair[1] for pair in scan];sources[method]='unchanged aggregation parent,identical256/core228 and calibration seed'
        else:
            scans[method]=[flat_measure(method,noise,model,h)['aggregate_std'] for h in STRENGTHS]
            sources[method]='fresh identical228 three-plane flat scan'
    # White target stays fixed; correlated target is selected ONLY from flat intersection.
    target=common_target(scans,previous['calibrations']['white']['target'] if not colored else None)
    record=dict(**target,scans={m:list(zip(STRENGTHS,v)) for m,v in scans.items()},scan_sources=sources,methods={})
    if target['status']!='common_target_available':return record
    control=flat_noise(26012602,colored)
    for method in METHODS:
        low,high=STRENGTHS[0],STRENGTHS[-1]
        for _ in range(10):
            h=float(np.sqrt(low*high));value=flat_measure(method,noise,model,h)['aggregate_std']
            if value>target['target']:low=h
            else:high=h
        h=float(np.sqrt(low*high));achieved=flat_measure(method,noise,model,h)
        record['methods'][method]=dict(h=h,calibration=achieved,control=flat_measure(method,control,model,h))
        if abs(achieved['aggregate_std']/target['target']-1)>.02:
            record['status']='abstained_matching_tolerance';return record
    record['status']='matched_on_calibration_only'
    return record


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    paths=[ROOT/'docs/validation/raw'/name for name in ('comparaison-agregation-patchs-bruit-v001-20261026T113556Z.json','supports-semantiques-bruit-v001-20261026T105634Z.json')]
    hashes=[sha256(p) for p in paths];previous,data=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    if previous['parents'][1]['sha256']!=hashes[1]:raise ValueError('Support parent changed')
    can_reuse=sha256(ROOT/'tests/study_noise_patch_aggregation.py')==previous['runner_sha256']
    selected={('6V1A0513.CR3','rock'),('6V1A0513.CR3','fabric'),('6V1A9890.CR3','hair'),('6V1A9890.CR3','letters')}
    start=datetime.now(timezone.utc);calibrations={};records=[]
    for colored in (False,True):
        key='binomial_correlated' if colored else 'white';model=noise_model(colored,False)
        cal=calibrate(colored,model,previous,can_reuse);calibrations[key]=cal
        print(key,'calibration',cal,flush=True)
        if cal['status']!='matched_on_calibration_only':continue
        for scene in data['scenes']:
            native=scene['native'];raw=native['raw']
            for sample in native['samples']:
                if (raw,sample['label']) not in selected:continue
                truth=np.array(sample['original_y_co_cg'],dtype=float).reshape(3,256,256)/.01
                for trial in range(2):
                    noise=np.stack([np.random.default_rng(26012610+trial+c*10).standard_normal((256,256)) for c in range(3)])
                    if colored:noise=color(noise)
                    metrics={}
                    for method in METHODS:
                        output,signal,residual=run_method(method,truth+noise,truth,model,cal['methods'][method]['h'])
                        metrics[method]=[measures(output[c],signal[c],residual[c],truth[c,14:-14,14:-14]) for c in range(3)]
                    for c in range(3):
                        records.append(dict(raw=raw,label=sample['label'],rect=sample['rect'],noise=key,trial=trial,plane=c,
                                            injected_sigma=.01,metrics={m:r[c] for m,r in metrics.items()}))
                print(raw,sample['label'],key,'three-way comparison complete',flush=True)
    if [sha256(p) for p in paths]!=hashes:raise ValueError('Parent changed during comparison')
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f"comparaison-point-commun-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),
        commit=git('rev-parse','HEAD'),local_changes=git('status','--short').splitlines(),runner_sha256=sha256(Path(__file__)),
        numpy_version=np.__version__,parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],
        dependencies={p:sha256(ROOT/'tests'/p) for p in ('study_noise_patch_aggregation.py','study_noise_semantic_comparison.py','study_noise_semantic_joint.py','study_noise_sure_feasibility.py')},
        calibrations=calibrations,records=records,
