"""Known single-plane forms in saved real-pair differences; conditional diagnostic,no new RAW."""
import argparse
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_semantic_comparison import reconstruct,measures,STRENGTHS
from study_noise_semantic_joint import reconstruct_joint
from study_noise_patch_aggregation import aggregate
from study_noise_common_operating_point import METHODS,common_target


def calibrate_difference(difference):
    difference=np.asarray(difference,dtype=float)
    if difference.shape!=(3,64,64) or not np.isfinite(difference).all():raise ValueError('Finite3plane64 differential required')
    outside=np.ones((64,64),dtype=bool);outside[12:52,12:52]=False
    sigma=np.std(difference[:,outside],axis=1)
    if np.any(sigma<=1e-10):raise ValueError('Insufficient marginal differential noise')
    means=np.mean(difference[:,outside],axis=1)
    noise=(difference-means[:,None,None])/sigma[:,None,None]
    plane_models=[]
    for c in range(3):
        offsets=[]
        for dy in range(-10,11):
            for dx in range(-10,11):
                if not (dx or dy):continue
                y0,y1=max(0,-dy),min(64,64-dy);x0,x1=max(0,-dx),min(64,64-dx)
                valid=outside[y0:y1,x0:x1]&outside[y0+dy:y1+dy,x0+dx:x1+dx]
                if int(valid.sum())<128:raise ValueError('Insufficient lag calibration samples')
                delta=noise[c,y0:y1,x0:x1]-noise[c,y0+dy:y1+dy,x0+dx:x1+dx]
                offsets.append((dy,dx,float(np.mean(delta[valid]**2))))
        plane_models.append(dict(variance=1.,offsets=offsets))
    joint=dict(variance=1.,offsets=[(p[0],p[1],float(np.mean([m['offsets'][i][2] for m in plane_models])))
                                    for i,p in enumerate(plane_models[0]['offsets'])])
    return noise,dict(sigma_y_co_cg=sigma.tolist(),outer_mean_y_co_cg=means.tolist(),outside_count=int(outside.sum()),
        normalized_centre_mean_y_co_cg=np.mean(noise[:,14:50,14:50],axis=(1,2)).tolist(),
        normalized_centre_std_y_co_cg=np.std(noise[:,14:50,14:50],axis=(1,2)).tolist(),
        normalized_cross_plane_correlation=np.corrcoef(noise[:,outside]).tolist(),plane_models=plane_models,joint_model=joint)


def known_signal(shape,channel,amplitude):
    if shape not in ('gaussian','step','stripes') or channel not in (0,1,2) or amplitude<=0:raise ValueError('Invalid known form')
    y,x=np.mgrid[:64,:64];x=x-32;y=y-32
    if shape=='gaussian':signal=np.exp(-(x*x+y*y)/(2*1.5**2))
    elif shape=='step':signal=np.where(x>=0,1.,-1.)
    else:signal=np.cos(2*np.pi*x/6.)*np.exp(-(x*x+y*y)/(2*5.**2))
    output=np.zeros((3,64,64));output[channel]=amplitude*signal
    return output


def run_method(method,image,truth,models,h):
    if method=='joint_overlap':return aggregate(image,truth,models['joint_model'],h)
    if method=='joint_centre':return reconstruct_joint(image,truth,models['joint_model'],h,(14,14,36,36))
    if method=='scalar':
        outputs=[reconstruct(image[c],truth[c],models['plane_models'][c],h,False,(14,14,36,36)) for c in range(3)]
        return tuple(np.stack([r[k] for r in outputs]) for k in range(3))
    raise ValueError('Unknown method')


def flat_measure(method,noise,models,h):
    output,_,_=run_method(method,noise,np.zeros_like(noise),models,h)
    std=np.std(output,axis=(1,2))
    return dict(aggregate_std=float(np.sqrt(np.mean(std*std))),per_plane_std=std.tolist())


def match(noise,models):
    scans={method:[flat_measure(method,noise,models,h)['aggregate_std'] for h in STRENGTHS] for method in METHODS}
    target=common_target(scans);result=dict(**target,scans={m:list(zip(STRENGTHS,v)) for m,v in scans.items()},methods={})
    if target['status']!='common_target_available':return result
    for method in METHODS:
        low,high=STRENGTHS[0],STRENGTHS[-1]
        for _ in range(10):
            h=float(np.sqrt(low*high))
            if flat_measure(method,noise,models,h)['aggregate_std']>target['target']:low=h
            else:high=h
        h=float(np.sqrt(low*high));achieved=flat_measure(method,noise,models,h)
        result['methods'][method]=dict(h=h,achieved=achieved)
        if abs(achieved['aggregate_std']/target['target']-1)>.02:
            result['status']='abstained_matching_tolerance';return result
    result['status']='matched_conditionally_same_residual_not_independent'
    return result


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    parent=ROOT/'docs/validation/raw/etude-reelle-bornee-nonlocal-bruit-v001-20261025T222336Z.json'
    digest=sha256(parent);data=json.loads(parent.read_text(encoding='utf-8'))
    start=datetime.now(timezone.utc);records=[];calibrations=[];exclusions=[]
    for pair in data['native']['pairs']:
        a,b=pair['a'],pair['b'];identity=dict(a=a['raw'],b=b['raw'],iso=a['iso'],camera=a['camera'])
        try:
            za=next(s for s in a['samples'] if s['kind']=='flat');zb=next(s for s in b['samples'] if s['kind']=='flat')
            if za['rect']!=zb['rect'] or a['iso']!=b['iso'] or a['camera']!=b['camera']:raise ValueError('Pair identity/geometry mismatch')
            if a['opening_chroma_median']!='FlatOnly' or b['opening_chroma_median']!='FlatOnly':raise ValueError('Opening mismatch')
            pa=np.array(za['original_y_co_cg'],dtype=float).reshape(3,64,64)
            pb=np.array(zb['original_y_co_cg'],dtype=float).reshape(3,64,64)
            noise,models=calibrate_difference((pa-pb)/np.sqrt(2.))
            cal=match(noise,models);calibrations.append(dict(**identity,rect=za['rect'],noise_calibration=models,matching=cal))
            print(identity,cal['status'],cal.get('target'),flush=True)
            if cal['status']!='matched_conditionally_same_residual_not_independent':continue
            for channel in range(3):
                for shape in ('gaussian','step','stripes'):
                    for amplitude in (3.,6.):
                        truth=known_signal(shape,channel,amplitude);core=truth[:,14:50,14:50];metrics={}
                        energy=float(np.mean(core[channel]**2))
                        for method in METHODS:
                            output,signal,residual=run_method(method,truth+noise,truth,models,cal['methods'][method]['h'])
                            per_plane=[measures(output[c],signal[c],residual[c],core[c]) for c in range(3)]
                            metrics[method]=dict(planes=per_plane,active_plane_response_projection=float(np.mean(output[channel]*core[channel]))/energy,
                                filtered_signal_projection=float(np.mean(signal[channel]*core[channel]))/energy,
                                other_planes_mean_mse=float(np.mean([per_plane[c]['surrogate_mse'] for c in range(3) if c!=channel])))
                        records.append(dict(**identity,rect=za['rect'],shape=shape,active_plane=channel,amplitude_in_outer_marginal_sigma=amplitude,metrics=metrics))
            print(a['iso'],'known forms complete',flush=True)
        except (ValueError,StopIteration) as error:
            exclusions.append(dict(**identity,reason=str(error)));print(identity,'excluded',str(error),flush=True)
    if sha256(parent)!=digest:raise ValueError('Parent changed')
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f"formes-residus-reels-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),
        commit=git('rev-parse','HEAD'),local_changes=git('status','--short').splitlines(),runner_sha256=sha256(Path(__file__)),numpy_version=np.__version__,
        parent=dict(path=str(parent),sha256=digest),calibrations=calibrations,records=records,exclusions=exclusions,
        dependencies={p:sha256(ROOT/'tests'/p) for p in ('study_noise_patch_aggregation.py','study_noise_semantic_joint.py','study_noise_semantic_comparison.py','study_noise_common_operating_point.py')},
        rules='Saved4realRCD/FlatOnly pair differences,oneflat-labelled64ROI perISO100/1600/6400/51200. D=(A-B)/sqrt2,normalize each plane by outside[12:52]mean/std,preserve cross-plane/spatial dependence. Marginal sigma units,not HH. Lagfloors measured outsidecentre,scalar own perplane,joint mean floor. One strength permethod/ISO from common flat residual target BEFORE injections,then3shapes*3single-activeplanes*2amplitudes=18cases peracceptedISO,allmeasured36core/halo14. No rotations,tiling or fake independent trials.',
        limitations='Pair difference may retain motion,drift or scene structure. Calibration and evaluation share the same residual and filtering context;NOT independent validation or deployable blind model. Only4noise fields;counterfactual forms are not72independent photos. Original RCD noise may be signal-dependent;additive replay cannot reproduce signal-dependent opening response. No trained model or production change. No claim of real-photo clean reference or absolute denoising success.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print(output,flush=True);print(len(records),'known cases;',len(exclusions),'exclusions',flush=True)


if __name__=='__main__':main()

