"""Experimental pilot DC / original-data contrast separation,via exact coefficient correction."""
import argparse
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_sure_feasibility import color
from study_noise_semantic_comparison import noise_model
from study_noise_patch_aggregation import aggregate
from study_noise_connected_reconstruction import cases
from study_noise_collaborative_wiener import reconstruct as parent_reconstruct,metrics,OFFSETS,PATCH,SPATIAL,GROUP,coefficient_variance,covariance_table


def dc_correction(raw,pilot,truth,pilot_signal,variance):
    arrays=[np.asarray(v,dtype=float) for v in (raw,pilot,truth,pilot_signal)]
    if any(v.shape!=(3,) or not np.isfinite(v).all() for v in arrays) or not np.isfinite(variance) or variance<0:raise ValueError('Finite three-plane DC values and variance>=0 required')
    raw,pilot,truth,pilot_signal=arrays
    gain=np.ones(3)
    np.divide(pilot*pilot,pilot*pilot+variance,out=gain,where=variance>0)
    return (pilot-gain*raw)/np.sqrt(425),(pilot_signal-gain*truth)/np.sqrt(425)


def reconstruct(observed,truth,colored):
    # Reuse the frozen parent outputs;add exact inverse-transform DC correction only.
    outputs,parent_audit=parent_reconstruct(observed,truth,colored)
    pilot,pilot_signal,_=aggregate(observed,truth,noise_model(colored,False),.8)
    corrections={m:np.zeros_like(observed) for m in ('raw_group','pilot_group')}
    signal_corrections={m:np.zeros_like(observed) for m in corrections}
    counts={m:np.zeros((64,64)) for m in corrections};cache={}
    for cy in tuple(range(20,44,3))+(43,):
        for cx in tuple(range(20,44,3))+(43,):
            ys=cy+OFFSETS[:,0,None]+PATCH[None,:,0];xs=cx+OFFSETS[:,1,None]+PATCH[None,:,1]
            raw=observed[:,ys,xs];pg=pilot[:,ys-14,xs-14]
            for mode,guide in (('raw_group',raw),('pilot_group',pg)):
                distance=np.mean((guide-guide[:,0:1,:])**2,axis=(0,2))
                indices=np.r_[0,np.argsort(distance[1:],kind='stable')[:16]+1]
                key=tuple(indices)
                if key not in cache:cache[key]=coefficient_variance(indices,covariance_table(colored))[0,0]
                y=ys[indices];x=xs[indices]
                groups=(raw[:,indices,:],pg[:,indices,:],truth[:,y,x],pilot_signal[:,y-14,x-14])
                dc=[(SPATIAL@g.swapaxes(-1,-2)@GROUP.T)[:,0,0] for g in groups]
                delta,clean_delta=dc_correction(*dc,cache[key])
                for c in range(3):
                    np.add.at(corrections[mode][c],(y,x),np.full(y.shape,delta[c]))
                    np.add.at(signal_corrections[mode][c],(y,x),np.full(y.shape,clean_delta[c]))
                np.add.at(counts[mode],(y,x),1.)
    audit={}
    for mode,new_name in (('raw_group','raw_dc_pilot'),('pilot_group','pilot_dc_pilot')):
        count=counts[mode][20:44,20:44]
        if np.any(count<=0):raise ValueError('Uncovered DC correction')
        delta=corrections[mode][:,20:44,20:44]/count[None]
        clean_delta=signal_corrections[mode][:,20:44,20:44]/count[None]
        out=outputs[mode][0]+delta;signal=outputs[mode][1]+clean_delta
        if not np.isfinite(out).all() or not np.isfinite(signal).all():raise ValueError('Nonfinite separated estimate')
        outputs[new_name]=(out,signal,out-signal)
        audit[new_name]=dict(dc_source='denoised_pilot',mean_output_correction=np.mean(delta,axis=(1,2)).tolist(),
            max_abs_output_correction=float(np.max(np.abs(delta))),parent=parent_audit[mode])
    return outputs,audit


def level_metrics(outputs,truth,identity,offset):
    result=metrics(outputs,truth+offset,identity)
    if identity is not None:
        c=identity['channel'];core=truth[c,20:44,20:44];energy=float(np.mean(core*core))
        for mode,(_,signal,_) in outputs.items():
            result[mode]['total_signal_projection']=result[mode].pop('signal_projection')
            result[mode]['contrast_signal_projection']=float(np.mean((signal[c]-offset)*core)/energy)
    return result


def run_field(noise,truth,identity,colored):
    rows=[];reference=None
    for offset in (0.,5.,20.):
        outputs,audit=reconstruct(noise+truth+offset,truth+offset,colored)
        if reference is None:reference=outputs
        translation={m:float(np.max(np.abs(out-offset-reference[m][0]))) for m,(out,_,_) in outputs.items()}
        if max(translation[m] for m in ('raw_dc_pilot','pilot_dc_pilot'))>1e-7:raise ValueError('Separated estimate violates paired translation contract')
        rows.append(dict(offset=offset,metrics=level_metrics(outputs,truth,identity,offset),audit=audit,translation_max_abs=translation))
    return rows


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    path=ROOT/'docs/validation/raw/collaboratif-wiener-deux-etapes-bruit-v001-20261026T152806Z.json'
