    start=datetime.now(timezone.utc);records=[];controls=[];challenges=[];serial=0
    for colored in (False,True):
        configurations=[(None,np.zeros((3,64,64)),16)]+[(identity,truth,1) for identity,truth in cases()]
        for identity,truth,trials in configurations:
            for trial in range(trials):
                seed=261026900000+serial;serial+=1
                noise=np.random.default_rng(seed).standard_normal((3,64,64))
                if colored:noise=color(noise)
                row=dict(noise='binomial_correlated' if colored else 'white',seed=seed,trial=trial,
