    if len(records)!=108 or len(controls)!=32 or len(challenges)!=9 or sha256(path)!=digest:raise ValueError('Incomplete or changed input')
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f"separation-dc-pilote-wiener-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,
