"""Spatial error/noise attribution of frozen DC-separated Wiener,not a new reconstruction."""
import argparse
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_sure_feasibility import color
from study_noise_empirical_forms import known_signal
from study_noise_wiener_dc_separation import reconstruct


def bands():
    x=np.arange(20,44);distance=np.abs(x-31.5)
    columns={'crossing':distance<2.5,'nearby':(distance>=2.5)&(distance<6.5),'farther':distance>=6.5}
    return {k:np.broadcast_to(v[None,:],(24,24)).copy() for k,v in columns.items()}


def decompose(output,signal,residual,truth):
    arrays=[np.asarray(v,dtype=float) for v in (output,signal,residual,truth)]
    if any(v.shape!=(3,24,24) or not np.isfinite(v).all() for v in arrays):raise ValueError('Finite three-plane24 arrays required')
    output,signal,residual,truth=arrays
    if not np.allclose(output,signal+residual,atol=1e-10,rtol=1e-10):raise ValueError('Invalid linear transport')
    error=output-truth;distortion=signal-truth
    terms=dict(mse=error*error,signal_distortion=distortion*distortion,residual_noise=residual*residual,cross=2*distortion*residual)
    if not np.allclose(terms['mse'],terms['signal_distortion']+terms['residual_noise']+terms['cross'],atol=1e-10,rtol=1e-10):raise ValueError('Invalid error budget')
    result=dict(full={k:np.mean(v,axis=(1,2)).tolist() for k,v in terms.items()},
        columns={k:np.mean(v,axis=1).tolist() for k,v in terms.items()},
        mean_error_columns=np.mean(error,axis=1).tolist(),mean_signal_bias_columns=np.mean(distortion,axis=1).tolist(),
        mean_noise_columns=np.mean(residual,axis=1).tolist(),bands={})
    for name,mask in bands().items():
        count=int(mask.sum());density={k:np.mean(v[:,mask],axis=1).tolist() for k,v in terms.items()}
        result['bands'][name]=dict(pixels=count,means=density,
            contributions={k:(np.asarray(values)*count/576).tolist() for k,values in density.items()},
            mean_error=np.mean(error[:,mask],axis=1).tolist())
    for k in terms:
        total=sum(np.asarray(b['contributions'][k]) for b in result['bands'].values())
        if not np.allclose(total,result['full'][k],atol=1e-10):raise ValueError('Band partition does not reproduce full error')
    return result


def verify_parent(result,parent):
    for mode,diagnostic in result.items():
        expected=parent['metrics'][mode]['planes']
        for name,key in (('mse','surrogate_mse'),('signal_distortion','signal_distortion_mse'),('residual_noise','residual_injected_noise_mse'),('cross','cross_term')):
            if not np.allclose(diagnostic['full'][name],[p[key] for p in expected],atol=1e-10,rtol=1e-10):raise ValueError('Parent metric replay mismatch')


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    path=ROOT/'docs/validation/raw/separation-dc-pilote-wiener-bruit-v001-20261026T154355Z.json'
    digest=sha256(path);parent=json.loads(path.read_text(encoding='utf-8'))
    if sha256(ROOT/'tests/study_noise_wiener_dc_separation.py')!=parent['runner_sha256']:raise ValueError('Separated reconstruction code changed')
    for n,h in parent['dependencies'].items():
        if sha256(ROOT/'tests'/n)!=h:raise ValueError('Parent dependency changed')
    selected=[r for r in parent['records'] if r['shape'] in ('step','stripes')]
    sources=[(r,False) for r in selected]+[(r,True) for r in parent['noise_controls']]
    if len(selected)!=24 or len(sources)!=56:raise ValueError('Unexpected fixed population')
    start=datetime.now(timezone.utc);records=[];controls=[]
    for r,flat in sources:
        colored=r['noise']=='binomial_correlated'
        noise=np.random.default_rng(r['seed']).standard_normal((3,64,64))
        if colored:noise=color(noise)
        truth=np.zeros_like(noise) if flat else known_signal(r['shape'],r['channel'],r['amplitude'])
        outputs,_=reconstruct(noise+truth,truth,colored);core=truth[:,20:44,20:44]
        result={mode:decompose(out,signal,residual,core) for mode,(out,signal,residual) in outputs.items()}
        verify_parent(result,r['levels'][0])
        record=dict(noise=r['noise'],seed=r['seed'],shape='flat' if flat else r['shape'],
            channel=None if flat else r['channel'],amplitude=0. if flat else r['amplitude'],methods=result)
        (controls if flat else records).append(record)
        if len(records)+len(controls) in (12,24,40,56):print('Spatial audits',len(records)+len(controls),'of56 complete',flush=True)
    if sha256(path)!=digest:raise ValueError('Parent changed')
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f"profils-spatiaux-transitions-wiener-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,
        started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),commit=git('rev-parse','HEAD'),
        local_changes=git('status','--short').splitlines(),runner_sha256=sha256(Path(__file__)),numpy_version=np.__version__,
        parent=dict(path=str(path),sha256=digest),records=records,noise_controls=controls,
        dependencies={n:sha256(ROOT/'tests'/n) for n in ('study_noise_wiener_dc_separation.py','study_noise_sure_feasibility.py','study_noise_empirical_forms.py')},
        coordinates=dict(columns_original_x=list(range(20,44)),edge_x=31.5,
            bands={name:dict(pixels=int(mask.sum()),columns=np.flatnonzero(mask[0]).astype(int).tolist()) for name,mask in bands().items()}),
        rules='No estimator changes. Replay24existingforms=12steps+12stripes,32sameflatfields atoffset0;verifyALL6methods fullMSE/distortion/noise/cross toparent1e-10. Store24column profiles and mean signederror/signalbias/noise. Edge31.5:crossing distance<2.5(4cols),nearby2.5<=d<6.5(8cols),farther>=6.5(12cols). Perband means and weighted contributions mustsum tofullbudget. SAMEstrips onflat/stripes are controls,not claims ofedges there. Truthused only for error and fixedlabelling,not filter.',
        limitations='Same56fields,notnewindependentquality;columnpixels/regions correlated,smallperfamilycounts. Farther relative to patch5/search9,NOT independent of wideNLMPilot or groupaggregation. Verticalstep only,knownGaussiancovariance notrealRCD. Oneoffset sufficient because parenttranslation verified;no newoffsetqualityclaim. No new candidate,threshold,SUREselector,production orphotos.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print(output,flush=True);print(len(records),'formprofiles,',len(controls),'flatprofiles',flush=True)


if __name__=='__main__':main()

